<?php
require_once __DIR__.'/database.php';appSessionStart();
header('Cache-Control: no-store');header('Referrer-Policy: no-referrer');header('X-Content-Type-Options: nosniff');header('X-Robots-Tag: noindex, nofollow');
require __DIR__.'/operations-bootstrap.php';
function stEsc($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
$_SESSION['staff_csrf']??=bin2hex(random_bytes(32));$invite=$_GET['invite']??'';$invited=null;$error='';
if($invite&&preg_match('/^[a-f0-9]{64}$/D',$invite))$invited=opsOne($pdo,'SELECT id,user_id,name,role FROM ops_staff WHERE invite_hash=? AND active=1 AND invite_expires>?',[hash('sha256',$invite),opsNow()]);
if($_SERVER['REQUEST_METHOD']==='POST')try{
    if(!hash_equals($_SESSION['staff_csrf'],$_POST['csrf']??''))throw new RuntimeException('Обновите страницу');
    $login=strtolower(trim($_POST['login']??''));$password=$_POST['password']??'';opsRateLimit($pdo,'staff-login:'.hash('sha256',($_SERVER['REMOTE_ADDR']??'').$runtimeConfig['webhook_secret']).':'.$login,10,900);
    if(!preg_match('/^[a-z0-9_.-]{4,60}$/D',$login))throw new RuntimeException('Логин: 4–60 латинских букв, цифр, точек или дефисов');
    if($invite){if(!$invited)throw new RuntimeException('Приглашение истекло или отключено');if(strlen($password)<10||strlen($password)>72)throw new RuntimeException('Пароль: от 10 до 72 байт');$staff=opsTx($pdo,(int)$invited['user_id'],function()use($pdo,$invite,$login,$password){$s=opsOne($pdo,'SELECT * FROM ops_staff WHERE invite_hash=? AND active=1 AND invite_expires>? FOR UPDATE',[hash('sha256',$invite),opsNow()]);if(!$s)throw new RuntimeException('Приглашение уже использовано');if(opsOne($pdo,'SELECT id FROM ops_staff WHERE login=?',[$login]))throw new RuntimeException('Такой логин уже занят');opsExec($pdo,'UPDATE ops_staff SET login=?,password_hash=?,invite_hash=NULL,invite_expires=NULL WHERE id=?',[$login,password_hash($password,PASSWORD_DEFAULT),$s['id']]);return $s;});}
    else{$staff=opsOne($pdo,'SELECT * FROM ops_staff WHERE login=? AND active=1',[$login]);if(!$staff||!password_verify($password,$staff['password_hash']??''))throw new RuntimeException('Неверный логин или пароль');}
    $owner=opsOne($pdo,'SELECT biz_name,location FROM users WHERE id=?',[$staff['user_id']]);if(!$owner)throw new RuntimeException('Рабочее пространство не найдено');session_regenerate_id(true);$_SESSION=['user_id'=>(int)$staff['user_id'],'staff_id'=>(int)$staff['id'],'staff_role'=>$staff['role'],'staff_name'=>$staff['name'],'biz_name'=>$owner['biz_name'],'location'=>$owner['location'],'user_phone'=>'','csrf'=>bin2hex(random_bytes(32))];header('Location: index.php#operations');exit;
}catch(Throwable $e){$error=$e instanceof PDOException?'Не удалось выполнить вход. Повторите позже.':$e->getMessage();}
?><!doctype html><html lang="ru"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Вход сотрудника · AulieAta</title><style>body{background:#f6f5ef;color:#122d22;font:16px system-ui;margin:0;padding:8vh 20px}main{max-width:430px;margin:auto;background:white;border:1px solid #e2e6dc;border-radius:22px;padding:32px}h1{font-size:26px}label{display:block;margin:20px 0 6px}input,button{box-sizing:border-box;width:100%;padding:14px;border-radius:10px;border:1px solid #d8dfd5;font:inherit}button{background:#122d22;color:white;margin-top:24px;cursor:pointer}p{line-height:1.6;color:#65766b}.error{color:#a52d24}a{color:inherit}</style><main><h1><?= $invited?'Присоединиться к команде':'Вход сотрудника' ?></h1><p><?= $invited?stEsc($invited['name']).', создайте свой логин и пароль. Приглашение используется один раз.':'Используйте данные, созданные по приглашению владельца.' ?></p><?php if($invite&&!$invited):?><p class="error">Приглашение недействительно. Попросите владельца выдать новое.</p><?php else:?><form method="post"><input type="hidden" name="csrf" value="<?=stEsc($_SESSION['staff_csrf'])?>"><label for="login">Логин</label><input id="login" name="login" required autocomplete="username" minlength="4" maxlength="60"><label for="password">Пароль</label><input id="password" name="password" type="password" required autocomplete="<?=$invited?'new-password':'current-password'?>" maxlength="72"><button><?=$invited?'Присоединиться':'Войти'?></button></form><?php endif;?><p class="error"><?=stEsc($error)?></p><a href="login.php">Вход владельца</a></main></html>
